-- 006: Akshay's test client. exclusive.thenameless.studio/akshay, shoot 1 already live.
-- Safe to run more than once. Remove it later with: delete from clients where slug = 'akshay';
insert into clients (slug, name, first_name, wa_number, status, config)
values ('akshay', 'Akshay Verma (test)', 'Akshay', '61473251606', 'handshake', '{"area":"Melbourne","akshayName":"Soubh"}'::jsonb)
on conflict (slug) do nothing;

insert into rounds (client_id, number, title, status, config, sent_at)
select c.id, 1, 'Shoot 1', 'live', '{"lede":"This one is the test run. Tap through it the way a client would, record a short drive, send a photo, and break whatever you can.","intro":"Each card is one line of a story. Nothing here is real yet, it is the house set a new client would start from.","secondsPerPrompt":75,"cards":[{"id":"name","claim":"Six months from now, when someone in your patch talks real estate, your name comes up first.","why":"That is the whole job. Recall, then trust. If there is something else you want people to remember after a few videos, say it on the mic."},{"id":"who","claim":"The people you most want are first-home buyers and upgrading families in your area.","why":"The content is aimed at them. If you know the decision they are stuck on, tell us in a voice note."},{"id":"proof","claim":"The numbers go first. Sold results, days on market, reviews.","why":"Results speak before introductions."},{"id":"start","claim":"The story starts before real estate. How you got here is the hook.","why":"Contrast is what people remember. You tell the turning point on the drive."},{"id":"office","claim":"The office is part of the story. There is a standard you want the team known for.","why":"One detail from the space, or one thing the people there should be known for. Say it on the mic if there is one."},{"id":"line","claim":"You have a line you say to clients that you actually believe, and the experience behind it.","why":"If you have one, say it and where it came from. If not, Not quite is fine."},{"id":"voice","claim":"You talk calm and straight, in whatever language the client speaks.","why":"Captions and voiceovers will sound like that too. A few phrases you actually use, and any words that feel unlike you, on the mic."},{"id":"camera","claim":"You would rather be heard than perform. Voiceover-led reels, you on screen when it adds weight.","why":"We build your comfort slowly. No scripts to memorise."},{"id":"format","claim":"Talking to a client feels more natural than talking to a lens. Conversations and walkthroughs first, direct to camera later.","why":"If there are two or three accounts or videos you enjoy, any industry, name them on the mic. What works there, and what would feel forced on you."},{"id":"lifestyle","claim":"The car and the watch show up in the background. They are never the point.","why":"Polished, not manufactured."},{"id":"family","claim":"Family stays off camera unless you say otherwise.","why":"Off limits by default. Anything else that should stay private, say it here or on the last drive prompt."},{"id":"rhythm","claim":"Stories almost every day, 12 to 15 reels a month, and you check with us before reposting anything.","why":"That is the operating rhythm from day one."}],"prompts":[{"q":"The moment real estate became serious for you.","h":"One turning point. Then how it still shows up in the way you work."},{"q":"A deal or a client decision that got difficult.","h":"What was at stake, what you did, what happened. A trade-off, or something you could not control."},{"q":"The experience that changed how you take responsibility.","h":"For a client or a team. What you learned, what you do differently now."},{"q":"A working day people rarely see.","h":"A recent one. What happened before or after the inspections, calls or auctions. A moment your judgment mattered."},{"q":"A client moment that shows what you bring.","h":"A handover, a hard conversation, a referral. What you did and any feedback you actually got."},{"q":"Optional. A setback that changed how you work.","h":"Only the part you are comfortable with, and what changed after. Tap Next to skip."},{"q":"Optional. An early moment in this city that explains who you are today.","h":"Belonging, ambition, finding your place. Leave it out if it feels too personal. Tap Next to skip."},{"q":"What should stay private.","h":"Family, history, opinions, filming situations you do not want. Say background only for anything we should hear but never use."}],"shootOptions":["Sat 15 Nov","Tue 18 Nov","Sat 22 Nov"],"photoAsks":["Any photo, just to test the drop"]}'::jsonb, now()
from clients c
where c.slug = 'akshay' and not exists (select 1 from rounds r where r.client_id = c.id and r.number = 1);

insert into events (client_id, type, payload)
select c.id, 'shoot_sent', '{"shoot":1,"how":"sql"}'::jsonb from clients c where c.slug = 'akshay' and not exists (select 1 from events e where e.client_id = c.id and e.type = 'shoot_sent');
